INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch02$PT134-S3-Q4$batch02$, 134, 3, 4, $batch02$Flaw$batch02$, $batch02$Journalist: A manufacturers’ trade group that has long kept its membership list secret inadvertently sent me a document listing hundreds of manufacturing companies. A representative of the trade group later confirmed that every company listed in the document does indeed belong to the trade group. Because Bruch Industries is not listed on the document, it is evidently not a member of the trade group.$batch02$, $batch02$The journalist’s reasoning in the argument is flawed in that the journalist$batch02$, $batch02$B$batch02$, true, $batch02$Batch 02 approved 2026-10-01; question text from local bank.$batch02$ FROM lr_sections s WHERE s.preptest=134 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT134-S3-Q4$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$A$batch02$, $batch02$gives no reason to think that Bruch Industries would want to belong to the trade group$batch02$, $batch02$Out of Scope$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT134-S3-Q4$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$A$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$B$batch02$, $batch02$does not present any evidence that the document names every member of the trade group$batch02$, $batch02$Correct$batch02$, true FROM lr_questions q WHERE q.qid=$batch02$PT134-S3-Q4$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$B$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$C$batch02$, $batch02$does not explain how it is that the trade group could have inadvertently sent out a secret document$batch02$, $batch02$Out of Scope$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT134-S3-Q4$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$C$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$D$batch02$, $batch02$presents no reason why Bruch Industries would not want its membership in the trade group to be known$batch02$, $batch02$Out of Scope$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT134-S3-Q4$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$D$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$E$batch02$, $batch02$takes for granted the accuracy of a statement by a representative who had a reason to withhold information$batch02$, $batch02$No Impact$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT134-S3-Q4$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$E$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch02$PT134-S3-Q4$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch02$Conclusion$batch02$, $batch02$Bruch Industries is not a member.$batch02$), (1, $batch02$Evidence$batch02$, $batch02$Every company on the list is a member. Bruch is not on the list.$batch02$), (2, $batch02$Evaluate$batch02$, $batch02$The rule is: on the list → member. The journalist reasons: not on the list → not a member. That is the illegal negation. The list could be partial. A class photo shows only students, but a student absent that day is still a student. Being listed is enough to prove membership; it is not required for it.$batch02$), (3, $batch02$Goal$batch02$, $batch02$Look for the formal answer (treating sufficient as necessary) or the conversational one (the list may not be complete).$batch02$)) v(position,label,body) WHERE q.qid=$batch02$PT134-S3-Q4$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$A$batch02$, $batch02$Whether Bruch wants to belong is beside the point. The question is whether the document proves it does not.$batch02$), ($batch02$B$batch02$, $batch02$The conclusion requires the list to be complete. If the document names only some members, Bruch's absence proves nothing. The journalist never shows the list is complete.$batch02$), ($batch02$C$batch02$, $batch02$How the document was sent has no bearing on whether it lists every member.$batch02$), ($batch02$D$batch02$, $batch02$Bruch's possible reasons for secrecy do not affect what the list shows.$batch02$), ($batch02$E$batch02$, $batch02$This tempts because the representative did have a reason for secrecy. But the representative only confirmed that the listed companies are members, and the journalist's inference about Bruch goes wrong even if that confirmation is perfectly accurate. The gap is the list's completeness.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT134-S3-Q4$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
